(function() {
  const tables = window.paperMindData?.tables || [];
  const sources = window.paperMindData?.sources || {};

  // Map table IDs to scenarios
  const scenarioMap = {
    'near-arb': 'p8-TABLE_1',
    'far-arb': 'p9-TABLE_III',
    'near-lin': 'p9-TABLE_II',
    'far-lin': 'p9-TABLE_IV'
  };

  const methodColors = {
    'A': '#e74c3c', // SI
    'B': '#f39c12', // Taylor
    'C': '#00CED1', // Proposed (Simplified)
    'D': '#2ecc71', // Proposed (Full)
    'E': '#95a5a6'  // CRLB/Theoretical
  };

  const methodLabels = {
    'A': 'SI Method',
    'B': 'Taylor Series',
    'C': 'Proposed (Simp)',
    'D': 'Proposed (Full)',
    'E': 'CRLB (Theoretical)'
  };

  const sensorRange = [3, 4, 5, 6, 7, 8, 9, 10];

  const scenarioSelect = document.getElementById('scenario-select');
  const sensorInput = document.getElementById('sensor-count');
  const sensorVal = document.getElementById('sensor-count-val');
  const resetBtn = document.getElementById('reset-btn');
  const canvas = document.getElementById('mse-chart');
  const ctx = canvas.getContext('2d');
  const tableBody = document.querySelector('#mse-table tbody');
  const tableNotes = document.getElementById('table-notes');
  const legendDiv = document.getElementById('chart-legend');

  let currentScenario = 'near-arb';
  let currentM = 9;
  let currentTableData = null;

  function parseValue(val) {
    if (val === 'no sol.' || val === null || val === undefined) return null;
    const num = Number(val);
    return isNaN(num) ? null : num;
  }

  function loadData(scenarioKey) {
    const tableId = scenarioMap[scenarioKey];
    const table = tables.find(t => t.id === tableId);
    if (!table) return null;

    // Process rows
    const processedRows = table.rows.map(row => {
      const values = {};
      sensorRange.forEach(m => {
        const key = `M = ${m}`;
        const rawVal = row.values[key];
        values[m] = parseValue(rawVal);
      });
      return {
        id: row.id,
        label: row.label,
        values: values
      };
    });

    return {
      title: table.title,
      notes: table.notes,
      rows: processedRows
    };
  }

  function drawChart(data) {
    if (!data) return;

    const width = canvas.width;
    const height = canvas.height;
    const padding = { top: 20, right: 20, bottom: 40, left: 60 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    ctx.clearRect(0, 0, width, height);

    // Determine Y scale (Logarithmic for better visualization of large differences)
    let maxY = -Infinity;
    let minY = Infinity;

    data.rows.forEach(row => {
      sensorRange.forEach(m => {
        const val = row.values[m];
        if (val !== null && val > 0) {
          if (val > maxY) maxY = val;
          if (val < minY) minY = val;
        }
      });
    });

    if (maxY === -Infinity) maxY = 1000;
    if (minY === Infinity) minY = 0.01;

    // Add padding to log scale
    const logMax = Math.log10(maxY * 10);
    const logMin = Math.log10(minY / 10);

    function getLogY(val) {
      if (val === null) return null;
      const logVal = Math.log10(val);
      return padding.top + chartHeight - ((logVal - logMin) / (logMax - logMin)) * chartHeight;
    }

    function getX(m) {
      const index = sensorRange.indexOf(m);
      return padding.left + (index / (sensorRange.length - 1)) * chartWidth;
    }

    // Draw Grid
    ctx.strokeStyle = '#ecf0f1';
    ctx.lineWidth = 1;
    ctx.font = '10px sans-serif';
    ctx.fillStyle = '#7f8c8d';
    ctx.textAlign = 'right';

    const yTicks = [logMin, (logMin+logMax)/2, logMax];
    yTicks.forEach(tick => {
      const y = padding.top + chartHeight - ((tick - logMin) / (logMax - logMin)) * chartHeight;
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();
      const labelVal = Math.pow(10, tick).toExponential(1);
      ctx.fillText(labelVal, padding.left - 5, y + 3);
    });

    // Draw X Axis Labels
    ctx.textAlign = 'center';
    sensorRange.forEach(m => {
      const x = getX(m);
      ctx.fillText(`M=${m}`, x, height - 10);
    });

    // Draw Lines
    data.rows.forEach(row => {
      if (row.label === 'A' && currentScenario.includes('lin')) return; // SI fails in linear

      ctx.beginPath();
      ctx.strokeStyle = methodColors[row.label] || '#000';
      ctx.lineWidth = 2;

      let started = false;
      sensorRange.forEach(m => {
        const val = row.values[m];
        if (val === null) {
          started = false;
          return;
        }
        const x = getX(m);
        const y = getLogY(val);
        if (!started) {
          ctx.moveTo(x, y);
          started = true;
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // Draw point at current M
      const currentVal = row.values[currentM];
      if (currentVal !== null) {
        const cx = getX(currentM);
        const cy = getLogY(currentVal);
        ctx.beginPath();
        ctx.arc(cx, cy, 4, 0, Math.PI * 2);
        ctx.fillStyle = methodColors[row.label] || '#000';
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.stroke();
      }
    });

    // Axis Labels
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.fillText('Mean Square Error (MSE) [Log Scale]', 0, 0);
    ctx.restore();

    ctx.textAlign = 'center';
    ctx.fillText('Number of Sensors (M)', width / 2, height - 5);
  }

  function updateTable(data) {
    if (!data) return;
    tableBody.innerHTML = '';

    data.rows.forEach(row => {
      if (row.label === 'A' && currentScenario.includes('lin')) return;

      const tr = document.createElement('tr');

      const th = document.createElement('td');
      th.textContent = row.label;
      th.style.fontWeight = 'bold';
      th.style.color = methodColors[row.label];
      tr.appendChild(th);

      sensorRange.forEach(m => {
        const td = document.createElement('td');
        const val = row.values[m];
        if (val === null) {
          td.textContent = '-';
          td.style.color = '#ccc';
        } else {
          td.textContent = val < 0.1 ? val.toExponential(2) : val.toFixed(2);
          if (m === currentM) {
            td.style.background = '#ecf0f1';
            td.style.fontWeight = 'bold';
          }
        }
        tr.appendChild(td);
      });

      tableBody.appendChild(tr);
    });

    tableNotes.innerHTML = data.notes.map(n => `<div>• ${n}</div>`).join('');
  }

  function updateLegend() {
    legendDiv.innerHTML = '';
    Object.keys(methodLabels).forEach(key => {
      if (key === 'A' && currentScenario.includes('lin')) return;

      const item = document.createElement('div');
      item.className = 'legend-item';

      const colorBox = document.createElement('div');
      colorBox.className = 'legend-color';
      colorBox.style.background = methodColors[key];

      const label = document.createElement('span');
      label.textContent = methodLabels[key];

      item.appendChild(colorBox);
      item.appendChild(label);
      legendDiv.appendChild(item);
    });
  }

  function render() {
    currentTableData = loadData(currentScenario);
    if (currentTableData) {
      drawChart(currentTableData);
      updateTable(currentTableData);
      updateLegend();
    }
  }

  scenarioSelect.addEventListener('change', (e) => {
    currentScenario = e.target.value;
    // Adjust M if out of range for new scenario
    const table = loadData(currentScenario);
    if (table) {
      const availableM = table.rows[0].values;
      // Find first valid M
      for (let m of sensorRange) {
        if (availableM[m] !== null) {
          currentM = m;
          break;
        }
      }
      sensorInput.value = currentM;
      sensorVal.textContent = currentM;
      render();
    }
  });

  sensorInput.addEventListener('input', (e) => {
    currentM = parseInt(e.target.value, 10);
    sensorVal.textContent = currentM;
    render();
  });

  resetBtn.addEventListener('click', () => {
    currentScenario = 'near-arb';
    currentM = 9;
    scenarioSelect.value = 'near-arb';
    sensorInput.value = 9;
    sensorVal.textContent = '9';
    render();
  });

  // Source button handling
  document.querySelectorAll('[data-source]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Host kernel handles this via data-source attribute
      // No action needed here other than ensuring attribute exists
    });
  });

  // Initial Render
  render();
})();
